export function farewellFor(name,key,context={}){return FAREWELLS[key%FAREWELLS.length].replaceAll('{name}',name).replaceAll('{fatalAttack}',context.beam?'the killing beam':'the final strike');}
export function recordFarewell(state,unit,random,location,context={}){if(unit.farewellKey!==undefined)return false;state.farewellUsed??=[];if(state.farewellUsed.length>=FAREWELLS.length)state.farewellUsed=[];const available=FAREWELLS.map((_,i)=>i).filter(i=>!state.farewellUsed.includes(i));unit.farewellKey=available[Math.min(available.length-1,Math.floor(random()*available.length))];state.farewellUsed.push(unit.farewellKey);unit.farewellText=farewellFor(unit.nickname||unit.species.name,unit.farewellKey,context);unit.deathLocation=location;recordMemorialDeath(state,unit);state.farewellNotices??=[];state.farewellNotices.push({uid:unit.uid,speciesId:unit.species.id,name:unit.nickname||unit.species.name,text:unit.farewellText});if(unit.heldItem){state.heldItems??={};state.heldItems[unit.heldItem]=(state.heldItems[unit.heldItem]||0)+1;unit.heldItem=null;}return true;}
